-- Classic 1.60: vanilla base stats (VMaNGOS pet_levelstats) of the pets creatures summon: Fire Elemental 575, Defias Companion 3450, Razormane Wolf 3939,
-- Wolfguard Worg 5058, Savannah Cub 5766, Crawler 6250, Skeletal Servant 8477, Voidwalker Minion 8996, Succubus Minion 10928, Scarlet Hound 10979,
-- Imp Minion 12922, Doomguard Minion 14385. Guardian::InitStatsForLevel takes their health, mana and armor (VMaNGOS Pet::InitStatsForLevel). Safe to run again.
DELETE FROM `pet_levelstats` WHERE `creature_entry` IN (575,3450,3939,5058,5766,6250,8477,8996,10928,10979,12922,14385);
